function seal(value,key=sessionKey){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',key,iv),body=Buffer.concat([cipher.update(JSON.stringify(value)),cipher.final()]);return iv.toString('base64url')+'.'+cipher.getAuthTag().toString('base64url')+'.'+body.toString('base64url');}
