 const payload={accessToken:token,accessTokenExpiresAt:new Date(claims.exp*1000+10).toISOString(),refreshToken:'synthetic-refresh-'+randomUUID(),idToken:'synthetic-id-'+randomUUID(),profile:{subjectId:options.subject??a,username:'Synthetic',name:'Synthetic',email:'synthetic@example.invalid',unknownProfileField:{keep:true}},unknownTopLevelField:{keep:['Synthetic',1,false]},...options.payload};
