 p.signedSessionPolicy={contractVersion:'cop-legacy-original-signed-session-policy-v1',issuer,authorizedParty:'cop-web',jwksUri,jwksSha256:hash(canonical(originalJwks)),encryptionKeyFingerprint:keyFingerprint(sessionSecret)};
 await entry(p,'session','cop_web_sessions',{session_id:id},[options.subject??a]);return {id,payload,cipher};
